  2	
  3	import com.pizza.api.config.PizzaProperties;
  4	import com.stripe.StripeClient;
  5	import com.stripe.exception.ApiConnectionException;
  6	import com.stripe.exception.RateLimitException;
  7	import com.stripe.exception.StripeException;
  8	import com.stripe.model.PaymentIntent;
  9	import com.stripe.model.PaymentMethod;
 10	import com.stripe.model.SetupIntent;
 11	import com.stripe.net.RequestOptions;
 12	import com.stripe.param.CustomerCreateParams;
 13	import com.stripe.param.PaymentIntentCreateParams;
 14	import com.stripe.param.PaymentMethodAttachParams;
 15	import com.stripe.param.SetupIntentCreateParams;
 16	import jakarta.annotation.PostConstruct;
 17	import java.math.BigDecimal;
 18	import java.math.RoundingMode;
 19	import java.util.Map;
 20	import java.util.UUID;
 21	import lombok.RequiredArgsConstructor;
 22	import org.slf4j.Logger;
 23	import org.slf4j.LoggerFactory;
 24	import org.springframework.resilience.annotation.Retryable;
 25	import org.springframework.stereotype.Service;
 26	
 27	/**
 28	 * Thin wrapper over the Stripe API.
 29	 *
 30	 * <p>Only ever runs server-side: the secret key must never reach a browser. The browser gets the
 31	 * publishable key plus a per-payment {@code clientSecret}, which is enough to confirm one card
 32	 * payment and nothing else.
 33	 */
 34	@Service
 35	@RequiredArgsConstructor
 36	public class StripeService {
 37	
 38	    private static final Logger log = LoggerFactory.getLogger(StripeService.class);
 39	
 40	    private final PizzaProperties properties;
 41	
 42	    private StripeClient stripe;
 43	
 44	    @PostConstruct
 45	    void init() {
 46	        String secretKey = properties.stripe().secretKey();
 47	        if (secretKey == null || secretKey.isBlank()) {
 48	            log.warn("pizza.stripe.secret-key is not set — checkout will fail. Put a test key in "
 49	                    + "application-local.properties and run with -Dspring-boot.run.profiles=local");
 50	            return;
 51	        }
 52	        if (secretKey.startsWith("sk_live_")) {
 53	            // A demo app should never be able to move real money by accident.
 54	            throw new IllegalStateException(
 55	                    "A LIVE Stripe key is configured. This demo only accepts test keys (sk_test_...)");
 56	        }
 57	        this.stripe = new StripeClient(secretKey);
 58	    }
 59	
 60	    public boolean isConfigured() {
 61	        return stripe != null;
 62	    }
 63	
 64	    /**
 65	     * Creates a PaymentIntent for an order.
 66	     *
 67	     * @param amount the order total, in dollars
 68	     * @param orderId our order's PUBLIC UUID, recorded as metadata so the webhook can trace it back
 69	     * @return the PaymentIntent, whose id and clientSecret we need
 70	     */
 71	    @Retryable(
 72	            includes = {ApiConnectionException.class, RateLimitException.class},
 73	            maxRetries = 3,
 74	            delay = 200,
 75	            multiplier = 2.0,
 76	            maxDelay = 2000,
 77	            jitter = 100)
 78	    public PaymentIntent createPaymentIntent(BigDecimal amount, UUID orderId, String receiptEmail)
 79	            throws StripeException {
 80	        requireConfigured();
 81	
 82	        PaymentIntentCreateParams.Builder params = PaymentIntentCreateParams.builder()
 83	                // Stripe works in the smallest currency unit — cents, as a long. Sending dollars
 84	                // here would undercharge by a factor of 100.
 85	                .setAmount(toCents(amount))
 86	                .setCurrency("usd")
 87	                .putAllMetadata(Map.of("orderId", String.valueOf(orderId)))
 88	                .setAutomaticPaymentMethods(PaymentIntentCreateParams.AutomaticPaymentMethods.builder()
 89	                        .setEnabled(true)
 90	                        .build());
 91	
 92	        if (receiptEmail != null && !receiptEmail.isBlank()) {
 93	            params.setReceiptEmail(receiptEmail);
 94	        }
 95	
 96	        // THE reason this method is safe to retry. Without an idempotency key, a request that
 97	        // succeeded at Stripe but whose response was lost to a network blip would be retried and
 98	        // create a SECOND PaymentIntent — the classic double-charge. Keyed on our own order id,
 99	        // Stripe recognises the replay and returns the original PaymentIntent instead.
100	        RequestOptions options =
101	                RequestOptions.builder().setIdempotencyKey("order-" + orderId).build();
102	
103	        return stripe.paymentIntents().create(params.build(), options);
104	    }
105	
106	    /**
107	     * A pure read, so it is idempotent by nature and needs no key to be safe to repeat.
108	     *
109	     * <p>Note which exceptions are listed. A dropped connection or a rate limit is worth trying
110	     * again — the request may well succeed a moment later. An {@code InvalidRequestException} is
111	     * not: the request was malformed, and sending it three more times just makes the same mistake
112	     * three more times, slower. Retrying the wrong exception turns a fast failure into a slow one.
113	     */
114	    @Retryable(
115	            includes = {ApiConnectionException.class, RateLimitException.class},
116	            maxRetries = 3,
117	            delay = 200,
118	            multiplier = 2.0,
119	            maxDelay = 2000,
120	            jitter = 100)
121	    public PaymentIntent retrieve(String paymentIntentId) throws StripeException {
122	        requireConfigured();
123	        return stripe.paymentIntents().retrieve(paymentIntentId);
124	    }
125	
126	    /**
127	     * Finds or creates the Stripe Customer a user's saved cards hang off.
128	     *
129	     * <p>Saved payment methods must be attached to a Customer; without one, a PaymentMethod is
130	     * single-use and cannot be charged again later.
131	     */
132	    public String ensureCustomer(String existingCustomerId, String email, String name) throws StripeException {
133	        requireConfigured();
134	        if (existingCustomerId != null && !existingCustomerId.isBlank()) {
135	            return existingCustomerId;
136	        }
137	
138	        CustomerCreateParams.Builder params = CustomerCreateParams.builder();
139	        if (email != null && !email.isBlank()) {
140	            params.setEmail(email);
141	        }
142	        if (name != null && !name.isBlank()) {
143	            params.setName(name);
144	        }
145	        return stripe.customers().create(params.build()).getId();
146	    }
147	
148	    /**
149	     * A SetupIntent lets the browser collect and store a card WITHOUT charging it.
150	     *
151	     * <p>This is the right primitive for "save a card for later": a PaymentIntent would take money
152	     * now, and collecting card details ourselves to store them would be both unnecessary and a
153	     * PCI problem.
154	     */
155	    public SetupIntent createSetupIntent(String customerId) throws StripeException {
156	        requireConfigured();
157	        return stripe.setupIntents()
158	                .create(SetupIntentCreateParams.builder()
159	                        .setCustomer(customerId)
160	                        .addPaymentMethodType("card")
161	                        .build());
162	    }
163	
164	    /** Attaches a collected PaymentMethod to the customer so it can be reused. */
165	    public PaymentMethod attachPaymentMethod(String paymentMethodId, String customerId) throws StripeException {
166	        requireConfigured();
167	        return stripe.paymentMethods()
168	                .attach(
169	                        paymentMethodId,
170	                        PaymentMethodAttachParams.builder()
171	                                .setCustomer(customerId)
172	                                .build());
173	    }
174	
175	    public PaymentMethod retrievePaymentMethod(String paymentMethodId) throws StripeException {
176	        requireConfigured();
177	        return stripe.paymentMethods().retrieve(paymentMethodId);
178	    }
179	
180	    /** Detaches a saved card so it can no longer be charged. */
181	    public void detachPaymentMethod(String paymentMethodId) throws StripeException {
182	        requireConfigured();
183	        stripe.paymentMethods().detach(paymentMethodId);
184	    }
185	
186	    /** 12.34 -> 1234. Scaling first avoids any floating-point surprise on the boundary. */
187	    static long toCents(BigDecimal amount) {
188	        return amount.setScale(2, RoundingMode.HALF_UP).movePointRight(2).longValueExact();
189	    }
190	
191	    private void requireConfigured() {
192	        if (stripe == null) {
193	            throw new IllegalStateException("Stripe is not configured. Set pizza.stripe.secret-key (see "
194	                    + "application-local.properties.example)");
195	        }
196	    }
197	}
