  3	import static org.springframework.http.HttpStatus.CREATED;
  4	import static org.springframework.http.HttpStatus.OK;
  5	
  6	import com.pizza.api.dto.OrderCreateDTO;
  7	import com.pizza.api.dto.OrderCreateResponseDTO;
  8	import com.pizza.api.dto.OrderDTO;
  9	import io.swagger.v3.oas.annotations.Operation;
 10	import io.swagger.v3.oas.annotations.security.SecurityRequirement;
 11	import io.swagger.v3.oas.annotations.tags.Tag;
 12	import jakarta.validation.Valid;
 13	import java.security.Principal;
 14	import java.util.UUID;
 15	import lombok.extern.slf4j.Slf4j;
 16	import org.springframework.beans.factory.annotation.Autowired;
 17	import org.springframework.data.domain.Page;
 18	import org.springframework.data.domain.PageRequest;
 19	import org.springframework.http.ResponseEntity;
 20	import org.springframework.web.bind.annotation.*;
 21	
 22	@Tag(name = "Orders", description = "Placing and tracking orders")
 23	@RequestMapping("/api/orders")
 24	@RestController
 25	@Slf4j
 26	public class CustomerOrderRestController {
 27	
 28	    @Autowired
 29	    private CustomerOrderService orderService;
 30	
 31	    /**
 32	     * Open to anonymous callers — that is what makes guest checkout work.
 33	     *
 34	     * <p>{@code Principal} is null for a guest and carries the email for a signed-in user, so one
 35	     * endpoint serves both without branching in the client.
 36	     */
 37	    @Operation(summary = "Place an order and open a Stripe PaymentIntent")
 38	    @PostMapping
 39	    public ResponseEntity<OrderCreateResponseDTO> createOrder(
 40	            @Valid @RequestBody OrderCreateDTO dto, Principal principal) {
 41	        String email = principal == null ? null : principal.getName();
 42	        log.info("POST /api/orders guest={}", email == null);
 43	        return new ResponseEntity<>(orderService.createOrder(dto, email), CREATED);
 44	    }
 45	
 46	    @Operation(summary = "Fetch an order by its public UUID")
 47	    @GetMapping("/{id}")
 48	    public ResponseEntity<OrderDTO> getOrder(@PathVariable UUID id) {
 49	        log.info("GET /api/orders/{}", id);
 50	        return new ResponseEntity<>(orderService.getOrderByPublicId(id), OK);
 51	    }
 52	
 53	    @Operation(
 54	            summary = "Re-check payment with Stripe",
 55	            description = "The confirmation page polls this, because webhooks do not reach localhost "
 56	                    + "unless `stripe listen` is running.")
 57	    @GetMapping("/{id}/payment-status")
 58	    public ResponseEntity<OrderDTO> getPaymentStatus(@PathVariable UUID id) {
 59	        return new ResponseEntity<>(orderService.refreshPaymentStatus(id), OK);
 60	    }
 61	
 62	    @Operation(summary = "The signed-in user's order history")
 63	    @SecurityRequirement(name = "bearerAuth")
 64	    @GetMapping("/mine")
 65	    public ResponseEntity<Page<OrderDTO>> getMyOrders(
 66	            Principal principal,
 67	            @RequestParam(defaultValue = "0") int page,
 68	            @RequestParam(defaultValue = "10") int size) {
 69	        return new ResponseEntity<>(orderService.getMyOrders(principal.getName(), PageRequest.of(page, size)), OK);
 70	    }
 71	}
 72	
 73	@Tag(name = "Admin · Orders", description = "Order management (ADMIN only)")
 74	@RequestMapping("/api/admin/orders")
 75	@RestController
 76	@SecurityRequirement(name = "bearerAuth")
 77	@Slf4j
 78	class AdminOrderRestController {
 79	
 80	    @Autowired
 81	    private CustomerOrderService orderService;
 82	
 83	    @Operation(summary = "All orders, newest first")
 84	    @GetMapping
 85	    public ResponseEntity<Page<OrderDTO>> getAllOrders(
 86	            @RequestParam(defaultValue = "0") int page, @RequestParam(defaultValue = "20") int size) {
 87	        log.info("GET /api/admin/orders page={} size={}", page, size);
 88	        return new ResponseEntity<>(orderService.getAllOrders(PageRequest.of(page, size)), OK);
 89	    }
 90	
 91	    @Operation(summary = "Move an order through its lifecycle")
 92	    @PatchMapping("/{id}/status")
 93	    public ResponseEntity<OrderDTO> updateStatus(@PathVariable UUID id, @RequestBody StatusUpdateDTO update) {
 94	        log.info("PATCH /api/admin/orders/{}/status -> {}", id, update.status());
 95	        return new ResponseEntity<>(orderService.updateStatus(id, update.status()), OK);
 96	    }
 97	
 98	    record StatusUpdateDTO(OrderStatus status) {}
 99	}

