 16	import org.springframework.web.bind.annotation.RequestBody;
 17	import org.springframework.web.bind.annotation.RequestHeader;
 18	import org.springframework.web.bind.annotation.RequestMapping;
 19	import org.springframework.web.bind.annotation.RestController;
 20	
 21	/**
 22	 * Receives payment events from Stripe.
 23	 *
 24	 * <p>Run locally with:
 25	 *
 26	 * <pre>stripe listen --forward-to localhost:8085/api/webhooks/stripe</pre>
 27	 *
 28	 * and put the printed {@code whsec_...} into {@code pizza.stripe.webhook-secret}.
 29	 */
 30	@RestController
 31	@RequestMapping("/api/webhooks")
 32	@RequiredArgsConstructor
 33	@Tag(name = "Webhooks", description = "Stripe callbacks (not called by the frontend)")
 34	public class StripeWebhookController {
 35	
 36	    private static final Logger log = LoggerFactory.getLogger(StripeWebhookController.class);
 37	
 38	    private final CustomerOrderService orderService;
 39	
 40	    private final PizzaProperties properties;
 41	
 42	    /**
 43	     * The raw body is required, not a parsed object: the signature is computed over the exact
 44	     * bytes Stripe sent, so re-serialising a DTO would invalidate it.
 45	     */
 46	    @PostMapping("/stripe")
 47	    @Operation(summary = "Stripe event receiver")
 48	    public ResponseEntity<String> handle(
 49	            @RequestBody String payload,
 50	            @RequestHeader(value = "Stripe-Signature", required = false) String signature) {
 51	
 52	        String webhookSecret = properties.stripe().webhookSecret();
 53	        if (webhookSecret == null || webhookSecret.isBlank()) {
 54	            log.warn("Received a webhook but pizza.stripe.webhook-secret is not set — ignoring");
 55	            return ResponseEntity.ok("ignored");
 56	        }
 57	
 58	        Event event;
 59	        try {
 60	            // THIS is the security check. Without signature verification the endpoint is public
 61	            // and anyone could POST a fake "payment succeeded" and get free pizza.
 62	            event = Webhook.constructEvent(payload, signature, webhookSecret);
 63	        } catch (SignatureVerificationException ex) {
 64	            log.warn("Rejected a webhook with a bad signature");
 65	            return ResponseEntity.badRequest().body("invalid signature");
 66	        }
 67	
 68	        if ("payment_intent.succeeded".equals(event.getType())) {
 69	            event.getDataObjectDeserializer()
 70	                    .getObject()
 71	                    .filter(PaymentIntent.class::isInstance)
 72	                    .map(PaymentIntent.class::cast)
 73	                    .ifPresent(intent -> orderService.markPaid(intent.getId()));
 74	        } else {
 75	            log.debug("Ignoring Stripe event type {}", event.getType());
 76	        }
 77	
 78	        // Always 200 for events we understood. A non-2xx makes Stripe retry, which is only
 79	        // desirable for genuine failures.
 80	        return ResponseEntity.ok("ok");
 81	    }
 82	}
