 22	@Tag(name = "Orders", description = "Placing and tracking orders")
 23	@RequestMapping("/api/orders")
 24	@RestController
 25	@Slf4j
 26	public class CustomerOrderRestController {
 27	
 28	    @Autowired
 29	    private CustomerOrderService orderService;
 30	
 31	    /**
 32	     * Open to anonymous callers — that is what makes guest checkout work.
 33	     *
 34	     * <p>{@code Principal} is null for a guest and carries the email for a signed-in user, so one
 35	     * endpoint serves both without branching in the client.
 36	     */
 37	    @Operation(summary = "Place an order and open a Stripe PaymentIntent")
 38	    @PostMapping
 39	    public ResponseEntity<OrderCreateResponseDTO> createOrder(
 40	            @Valid @RequestBody OrderCreateDTO dto, Principal principal) {
 41	        String email = principal == null ? null : principal.getName();
 42	        log.info("POST /api/orders guest={}", email == null);
 43	        return new ResponseEntity<>(orderService.createOrder(dto, email), CREATED);
 44	    }
