  1	import { useEffect, useId, useState } from 'react';
  2	import { Alert, Button, Card, Col, Container, Form, Row, Spinner } from 'react-bootstrap';
  3	import { useNavigate } from 'react-router-dom';
  4	import { Elements } from '@stripe/react-stripe-js';
  5	import { useCart } from '../context/CartContext';
  6	import { useAuth } from '../context/AuthContext';
  7	import { ApiError, api } from '../lib/api';
  8	import { stripePromise } from '../lib/stripe';
  9	import { formatMoney, lineTotal } from '../lib/money';
 10	import { StripePaymentForm } from '../components/StripePaymentForm';
 11	import { profileApi } from '../lib/profileApi';
 12	import type { Address, OrderCreateRequest, OrderCreateResponse } from '../types';
 13	
 14	/**
 15	 * Checkout, in two steps.
 16	 *
 17	 * <p>1. Collect contact/address and POST /api/orders. The server prices the cart from the database,
 18	 * saves the order as PENDING_PAYMENT and opens a Stripe PaymentIntent, returning its clientSecret.
 19	 *
 20	 * <p>2. Render Stripe Elements against that clientSecret and confirm the card.
 21	 *
 22	 * <p>The order has to exist before the payment form can render, because the PaymentIntent is what
 23	 * the card form is confirming. That ordering is why this is two steps rather than one big submit.
 24	 *
 25	 * <p>Note what is NOT sent in step 1: no prices. The server decides what the cart costs.
 26	 */
 27	export function CheckoutPage() {
 28	  const { items, totals, orderType, setOrderType, clear } = useCart();
 29	  const { user, isAuthenticated } = useAuth();
 30	  const navigate = useNavigate();
 31	
 32	  const formId = useId();
 33	  const [validated, setValidated] = useState(false);
 34	  const [submitting, setSubmitting] = useState(false);
 35	  const [error, setError] = useState<string | null>(null);
 36	
 37	  // Set once the order exists server-side; its presence is what advances us to step 2.
 38	  const [created, setCreated] = useState<OrderCreateResponse | null>(null);
 39	
 40	  /*
 41	   * Saved addresses, for signed-in customers.
 42	   *
 43	   * `NEW` is a sentinel meaning "type a fresh address instead of using a saved one". Modelling it
 44	   * as one selection value rather than a separate boolean keeps the radio group honest: exactly
 45	   * one option is selected at any time.
 46	   */
 47	  const NEW_ADDRESS = 'NEW';
 48	  const [addresses, setAddresses] = useState<Address[]>([]);
 49	  const [selectedAddressId, setSelectedAddressId] = useState<string>(NEW_ADDRESS);
 50	
 51	  const [form, setForm] = useState({
 52	    customerName: user?.fullName ?? '',
 53	    email: user?.email ?? '',
 54	    phone: '',
 55	    addressLine1: '',
 56	    city: '',
 57	    state: '',
 58	    postalCode: '',
 59	  });
 60	
 61	  const isDelivery = orderType === 'DELIVERY';
 62	  // Only ask for typed address fields when there is no saved address selected.
 63	  const usingNewAddress = selectedAddressId === NEW_ADDRESS;
 64	
 65	  /*
 66	   * Load the customer's saved addresses and preselect their PRIMARY one.
 67	   *
 68	   * Guests skip this entirely — they have no account, so there is nothing to load.
 69	   */
 70	  useEffect(() => {
 71	    if (!isAuthenticated) return;
 72	
 73	    let cancelled = false;
 74	    profileApi
 75	      .listAddresses()
 76	      .then((saved) => {
 77	        if (cancelled) return;
 78	        setAddresses(saved);
 79	
 80	        const primary = saved.find((a) => a.primary) ?? saved[0];
 81	        if (primary) {
 82	          setSelectedAddressId(primary.id);
 83	          setForm((current) => ({
 84	            ...current,
 85	            phone: current.phone || (primary.phone ?? ''),
 86	          }));
 87	        }
 88	      })
 89	      .catch(() => {
 90	        // A profile that will not load must not block checkout — fall back to typing an address.
 91	      });
 92	
 93	    return () => {
 94	      cancelled = true;
 95	    };
 96	  }, [isAuthenticated]);
 97	
 98	  function updateField(field: keyof typeof form, value: string) {
 99	    // Functional update: safe even if several updates are batched together.
100	    setForm((current) => ({ ...current, [field]: value }));
101	  }
102	
103	  /** The address fields to send: from the chosen saved address, or from the form. */
104	  function addressFields() {
105	    if (!usingNewAddress) {
106	      const chosen = addresses.find((a) => a.id === selectedAddressId);
107	      if (chosen) {
108	        return {
109	          addressLine1: chosen.line1,
110	          addressLine2: chosen.line2 ?? undefined,
111	          city: chosen.city,
112	          state: chosen.state,
113	          postalCode: chosen.postalCode,
114	        };
115	      }
116	    }
117	    return {
118	      addressLine1: form.addressLine1,
119	      city: form.city,
120	      state: form.state,
121	      postalCode: form.postalCode,
122	    };
123	  }
124	
125	  async function handleCreateOrder(event: React.FormEvent<HTMLFormElement>) {
126	    event.preventDefault();
127	    const formElement = event.currentTarget;
128	
129	    // Bootstrap's validation styling is driven by the browser's own constraint validation API.
130	    if (!formElement.checkValidity()) {
131	      event.stopPropagation();
132	      setValidated(true);
133	      return;
134	    }
135	
136	    setSubmitting(true);
137	    setError(null);
138	
139	    const payload: OrderCreateRequest = {
140	      orderType,
141	      customerName: form.customerName,
142	      // Ignored by the server when a token is present — the account's email wins.
143	      guestEmail: form.email,
144	      phone: form.phone || undefined,
145	      // A saved address wins when one is selected; otherwise use what was typed.
146	      ...(isDelivery ? addressFields() : {}),
147	      items: items.map((item) => ({
148	        productId: item.productId,
149	        size: item.size,
150	        crustId: item.crustId,
151	        toppingIds: item.toppings.map((t) => t.id),
152	        quantity: item.quantity,
153	      })),
154	    };
155	
156	    try {
157	      const response = await api.post<OrderCreateResponse>('/api/orders', payload, {
158	        auth: isAuthenticated,
159	      });
160	      setCreated(response);
161	    } catch (err) {
162	      setError(
163	        err instanceof ApiError
164	          ? err.message
165	          : 'Could not reach the server. Is the API running on port 8085?',
166	      );
167	    } finally {
168	      setSubmitting(false);
169	    }
170	  }
171	
172	  /** Stripe accepted the card. The cart is done; the confirmation page confirms with the server. */
173	  function handlePaymentSuccess() {
174	    const orderId = created!.order.id;
175	    clear();
176	    navigate(`/order-confirmation/${orderId}`);
177	  }
178	
179	  if (items.length === 0 && !created) {
180	    return (
181	      <Container className="py-5">
182	        <Alert variant="light" className="text-center border">
183	          <h1 className="h5">Your cart is empty</h1>
184	          <p className="text-muted">Add a pizza before checking out.</p>
185	          <Button variant="primary" onClick={() => navigate('/menu')}>
186	            Browse the menu
187	          </Button>
188	        </Alert>
189	      </Container>
190	    );
191	  }
192	
193	  return (
194	    <Container className="py-4">
195	      <h1 className="h3 fw-bold mb-4">Checkout</h1>
196	
197	      {error && (
198	        <Alert variant="danger" onClose={() => setError(null)} dismissible>
199	          {error}
200	        </Alert>
201	      )}
202	
203	      <Row className="g-4">
204	        <Col lg={7}>
205	          {created ? (
206	            /* ---------------------------------------------- step 2: pay */
207	            <Card className="border-0 shadow-sm">
208	              <Card.Body>
209	                <h2 className="h6 fw-bold text-uppercase text-muted mb-3">Payment</h2>
210	
211	                {created.clientSecret ? (
212	                  /*
213	                   * `key` on Elements matters: the provider reads clientSecret once, at mount.
214	                   * Keying it to the secret guarantees a fresh Elements instance if the customer
215	                   * ever goes back and creates a different order.
216	                   */
217	                  <Elements
218	                    key={created.clientSecret}
219	                    stripe={stripePromise}
220	                    options={{
221	                      clientSecret: created.clientSecret,
222	                      appearance: { theme: 'stripe', variables: { colorPrimary: '#d8102a' } },
223	                    }}
224	                  >
225	                    <StripePaymentForm
226	                      total={created.order.total}
227	                      onSuccess={handlePaymentSuccess}
228	                    />
229	                  </Elements>
230	                ) : (
231	                  <Alert variant="warning" className="mb-0">
232	                    The server created order <strong>{created.order.id}</strong> but returned no
233	                    Stripe client secret, which means no Stripe key is configured on the backend.
234	                    Set <code>pizza.stripe.secret-key</code> in{' '}
235	                    <code>application-local.properties</code> and run with the{' '}
236	                    <code>local</code> profile.
237	                  </Alert>
238	                )}
239	              </Card.Body>
240	            </Card>
241	          ) : (
242	            /* ---------------------------------------------- step 1: details */
243	            <Form noValidate validated={validated} onSubmit={handleCreateOrder} id="checkout-form">
244	              {!isAuthenticated && (
245	                <Alert variant="light" className="border">
246	                  Checking out as a guest.{' '}
247	                  <Alert.Link onClick={() => navigate('/login')} role="button">
248	                    Sign in
249	                  </Alert.Link>{' '}
250	                  to save this order to your account — entirely optional.
251	                </Alert>
252	              )}
253	
254	              {/*
255	                Delivery vs pickup, chosen here as well as in the cart drawer. It changes the
256	                price (a delivery fee) and which fields are required, so making the customer go
257	                back to the drawer to change their mind is needless friction.
258	              */}
259	              <Card className="mb-4 border-0 shadow-sm">
260	                <Card.Body>
261	                  <h2 className="h6 fw-bold text-uppercase text-muted mb-3">How would you like it?</h2>
262	                  <div className="d-flex gap-2 flex-wrap">
263	                    <Button
264	                      type="button"
265	                      variant={isDelivery ? 'primary' : 'outline-primary'}
266	                      aria-pressed={isDelivery}
267	                      onClick={() => setOrderType('DELIVERY')}
268	                    >
269	                      Delivery
270	                      <span className="d-block small fw-normal">
271	                        {formatMoney(3.99)} fee
272	                      </span>
273	                    </Button>
274	                    <Button
275	                      type="button"
276	                      variant={!isDelivery ? 'primary' : 'outline-primary'}
277	                      aria-pressed={!isDelivery}
278	                      onClick={() => setOrderType('CARRYOUT')}
279	                    >
280	                      Pick up
281	                      <span className="d-block small fw-normal">No fee</span>
282	                    </Button>
283	                  </div>
284	                </Card.Body>
285	              </Card>
286	
287	              <Card className="mb-4 border-0 shadow-sm">
288	                <Card.Body>
289	                  <h2 className="h6 fw-bold text-uppercase text-muted mb-3">Contact</h2>
290	                  <Row className="g-3">
291	                    <Col md={6}>
292	                      <Form.Label htmlFor={`${formId}-name`}>Name</Form.Label>
293	                      <Form.Control
294	                        id={`${formId}-name`}
295	                        required
296	                        value={form.customerName}
297	                        onChange={(e) => updateField('customerName', e.target.value)}
298	                        autoComplete="name"
299	                      />
300	                      <Form.Control.Feedback type="invalid">
301	                        Please tell us who the order is for.
302	                      </Form.Control.Feedback>
303	                    </Col>
304	                    <Col md={6}>
305	                      <Form.Label htmlFor={`${formId}-email`}>Email</Form.Label>
306	                      <Form.Control
307	                        id={`${formId}-email`}
308	                        type="email"
309	                        required
310	                        value={form.email}
311	                        onChange={(e) => updateField('email', e.target.value)}
312	                        autoComplete="email"
313	                      />
314	                      <Form.Control.Feedback type="invalid">
315	                        We need a valid email to send the receipt.
316	                      </Form.Control.Feedback>
317	                    </Col>
318	                    <Col md={6}>
319	                      <Form.Label htmlFor={`${formId}-phone`}>Phone</Form.Label>
320	                      <Form.Control
321	                        id={`${formId}-phone`}
322	                        type="tel"
323	                        value={form.phone}
324	                        onChange={(e) => updateField('phone', e.target.value)}
325	                        autoComplete="tel"
326	                      />
327	                    </Col>
328	                  </Row>
329	                </Card.Body>
330	              </Card>
331	
332	              {/* Address fields only exist for delivery — the toggle lives in the cart drawer. */}
333	              {isDelivery && (
334	                <Card className="mb-4 border-0 shadow-sm">
335	                  <Card.Body>
336	                    <h2 className="h6 fw-bold text-uppercase text-muted mb-3">Delivery address</h2>
337	
338	                    {/* Saved addresses, primary preselected. Guests never see this. */}
339	                    {addresses.length > 0 && (
340	                      <div className="mb-3">
341	                        {addresses.map((address) => (
342	                          <Form.Check
343	                            key={address.id}
344	                            type="radio"
345	                            name="savedAddress"
346	                            id={`address-${address.id}`}
347	                            checked={selectedAddressId === address.id}
348	                            onChange={() => setSelectedAddressId(address.id)}
349	                            label={
350	                              <span>
351	                                <span className="fw-semibold">{address.label || 'Address'}</span>
352	                                {address.primary && (
353	                                  <span className="badge bg-success ms-2">primary</span>
354	                                )}
355	                                <span className="d-block text-muted small">
356	                                  {address.line1}, {address.city}, {address.state}{' '}
357	                                  {address.postalCode}
358	                                </span>
359	                              </span>
360	                            }
361	                          />
362	                        ))}
363	                        <Form.Check
364	                          type="radio"
365	                          name="savedAddress"
366	                          id="address-new"
367	                          checked={usingNewAddress}
368	                          onChange={() => setSelectedAddressId(NEW_ADDRESS)}
369	                          label="Use a different address"
370	                        />
371	                      </div>
372	                    )}
373	
374	                    {usingNewAddress && (
375	                    <Row className="g-3">
376	                      <Col xs={12}>
377	                        <Form.Label htmlFor={`${formId}-address`}>Street address</Form.Label>
378	                        <Form.Control
379	                          id={`${formId}-address`}
380	                          required
381	                          value={form.addressLine1}
382	                          onChange={(e) => updateField('addressLine1', e.target.value)}
383	                          autoComplete="address-line1"
384	                        />
385	                        <Form.Control.Feedback type="invalid">
386	                          We cannot deliver without a street address.
387	                        </Form.Control.Feedback>
388	                      </Col>
389	                      <Col md={5}>
390	                        <Form.Label htmlFor={`${formId}-city`}>City</Form.Label>
391	                        <Form.Control
392	                          id={`${formId}-city`}
393	                          required
394	                          value={form.city}
395	                          onChange={(e) => updateField('city', e.target.value)}
396	                          autoComplete="address-level2"
397	                        />
398	                      </Col>
399	                      <Col md={3}>
400	                        <Form.Label htmlFor={`${formId}-state`}>State</Form.Label>
401	                        <Form.Control
402	                          id={`${formId}-state`}
403	                          required
404	                          value={form.state}
405	                          onChange={(e) => updateField('state', e.target.value)}
406	                          autoComplete="address-level1"
407	                        />
408	                      </Col>
409	                      <Col md={4}>
410	                        <Form.Label htmlFor={`${formId}-zip`}>ZIP</Form.Label>
411	                        <Form.Control
