424	                    )}
425	                  </Card.Body>
426	                </Card>
427	              )}
428	            </Form>
429	          )}
430	        </Col>
431	
432	        <Col lg={5}>
433	          <Card className="border-0 shadow-sm sticky-summary">
434	            <Card.Body>
435	              <h2 className="h6 fw-bold text-uppercase text-muted mb-3">
436	                Order summary · {orderType.toLowerCase()}
437	              </h2>
438	
439	              {(created ? created.order.items : items).map((item) => (
440	                <div
441	                  key={'lineId' in item ? item.lineId : item.id}
