  6	interface Props {
  7	  total: number;
  8	  onSuccess: () => void;
  9	}
 10	
 11	/**
 12	 * The card form.
 13	 *
 14	 * <p>Must render INSIDE an {@code <Elements>} provider — {@code useStripe} and {@code useElements}
 15	 * read from its context and return null otherwise.
 16	 *
 17	 * <p>The card number never touches our servers or even our JavaScript: {@code PaymentElement}
 18	 * renders an iframe hosted by Stripe, so the details go straight from the customer's browser to
 19	 * Stripe. That is what keeps this app out of PCI scope.
 20	 */
 21	export function StripePaymentForm({ total, onSuccess }: Props) {
 22	  const stripe = useStripe();
 23	  const elements = useElements();
 24	
 25	  const [submitting, setSubmitting] = useState(false);
 26	  const [error, setError] = useState<string | null>(null);
 27	
 28	  async function handleSubmit(event: React.FormEvent) {
 29	    event.preventDefault();
 30	
 31	    // Both are null until Stripe.js has finished loading.
 32	    if (!stripe || !elements) return;
 33	
 34	    setSubmitting(true);
 35	    setError(null);
 36	
 37	    const result = await stripe.confirmPayment({
 38	      elements,
 39	      /*
 40	       * `if_required` keeps the customer inside our SPA for ordinary card payments, and only
 41	       * redirects when the payment method genuinely demands it — 3D Secure, or a bank redirect.
 42	       * `return_url` is where Stripe sends them back to in that case.
 43	       */
 44	      redirect: 'if_required',
 45	      confirmParams: {
 46	        return_url: `${window.location.origin}/checkout`,
 47	      },
 48	    });
 49	
 50	    if (result.error) {
 51	      // card_error and validation_error are safe to show; anything else is a generic message,
 52	      // because the detail can leak information about the payment infrastructure.
 53	      const message =
 54	        result.error.type === 'card_error' || result.error.type === 'validation_error'
 55	          ? (result.error.message ?? 'Your card was declined.')
 56	          : 'Something went wrong taking the payment. Please try again.';
 57	      setError(message);
 58	      setSubmitting(false);
 59	      return;
 60	    }
 61	
 62	    /*
 63	     * Success here means Stripe accepted the payment. Our order is still PENDING_PAYMENT until
 64	     * the backend hears about it — via the webhook, or via the confirmation page polling
 65	     * /payment-status. We never mark an order paid from the browser: anyone can call our API.
 66	     */
 67	    onSuccess();
 68	  }
 69	
 70	  return (
 71	    <form onSubmit={handleSubmit}>
 72	      <PaymentElement />
 73	
 74	      {error && (
 75	        <Alert variant="danger" className="mt-3 mb-0">
 76	          {error}
 77	        </Alert>
 78	      )}
 79	
 80	      <Button
 81	        type="submit"
 82	        variant="primary"
 83	        size="lg"
 84	        className="w-100 mt-3"
 85	        disabled={!stripe || submitting}
 86	      >
 87	        {submitting ? (
 88	          <>
 89	            <Spinner as="span" animation="border" size="sm" className="me-2" />
 90	            Processing…
 91	          </>
 92	        ) : (
 93	          `Pay ${formatMoney(total)}`
 94	        )}
 95	      </Button>
 96	
 97	      <p className="small text-muted mt-2 mb-0">
 98	        Test mode — use card <code>4242 4242 4242 4242</code>, any future expiry, any CVC.
 99	      </p>
100	    </form>
101	  );
102	}
