  1	package com.pizza.api.entity.order;
  2	
  3	import com.pizza.api.dto.EntityDTOMapper;
  4	import com.pizza.api.dto.OrderCreateDTO;
  5	import com.pizza.api.dto.OrderCreateResponseDTO;
  6	import com.pizza.api.dto.OrderDTO;
  7	import com.pizza.api.entity.user.User;
  8	import com.pizza.api.entity.user.UserDAO;
  9	import com.pizza.api.exception.ApiException;
 10	import com.pizza.api.payment.StripeService;
 11	import com.stripe.exception.StripeException;
 12	import com.stripe.model.PaymentIntent;
 13	import com.stripe.model.PaymentMethod;
 14	import java.util.UUID;
 15	import lombok.extern.slf4j.Slf4j;
 16	import org.springframework.beans.factory.annotation.Autowired;
 17	import org.springframework.context.ApplicationEventPublisher;
 18	import org.springframework.data.domain.Page;
 19	import org.springframework.data.domain.Pageable;
 20	import org.springframework.stereotype.Service;
 21	import org.springframework.transaction.annotation.Transactional;
 22	
 23	@Service
 24	@Slf4j
 25	public class CustomerOrderServiceImpl implements CustomerOrderService {
 26	
 27	    @Autowired
 28	    private CustomerOrderDAO orderDAO;
 29	
 30	    @Autowired
 31	    private UserDAO userDAO;
 32	
 33	    @Autowired
 34	    private EntityDTOMapper mapper;
 35	
 36	    @Autowired
 37	    private PricingService pricingService;
 38	
 39	    @Autowired
 40	    private StripeService stripeService;
 41	
 42	    @Autowired
 43	    private ApplicationEventPublisher events;
 44	
 45	    @Override
 46	    @Transactional
 47	    public OrderCreateResponseDTO createOrder(OrderCreateDTO dto, String userEmail) {
 48	        // Guest checkout is the null-user path. A signed-in order attaches the account instead.
 49	        User user = userEmail == null ? null : userDAO.findByEmail(userEmail).orElse(null);
 50	
 51	        if (user == null && (dto.guestEmail() == null || dto.guestEmail().isBlank())) {
 52	            throw ApiException.badRequest("An email address is required to check out as a guest");
 53	        }
 54	        if (dto.orderType() == OrderType.DELIVERY
 55	                && (dto.addressLine1() == null || dto.addressLine1().isBlank())) {
 56	            throw ApiException.badRequest("A delivery address is required for delivery orders");
 57	        }
 58	
 59	        // Every figure below comes from the database, never from the request.
 60	        PricingService.PricedOrder priced = pricingService.price(dto);
 61	
 62	        CustomerOrder order = CustomerOrder.builder()
 63	                .user(user)
 64	                .guestEmail(user == null ? dto.guestEmail() : null)
 65	                .customerName(dto.customerName())
 66	                .phone(dto.phone())
 67	                .orderType(dto.orderType())
 68	                .status(OrderStatus.PENDING_PAYMENT)
 69	                .addressLine1(dto.addressLine1())
 70	                .addressLine2(dto.addressLine2())
 71	                .city(dto.city())
 72	                .state(dto.state())
 73	                .postalCode(dto.postalCode())
 74	                .subtotal(priced.subtotal())
 75	                .tax(priced.tax())
 76	                .deliveryFee(priced.deliveryFee())
 77	                .total(priced.total())
 78	                .build();
 79	
 80	        priced.items().forEach(order::addItem);
 81	
 82	        // Saved BEFORE talking to Stripe, so the PaymentIntent can carry a real order id and an
 83	        // abandoned checkout still leaves a record.
 84	        CustomerOrder saved = orderDAO.save(order);
 85	        log.info("Created order {} for {}", saved.getPublicId(), saved.contactEmail());
 86	
 87	        String clientSecret = null;
 88	        if (stripeService.isConfigured()) {
 89	            try {
 90	                PaymentIntent intent =
 91	                        stripeService.createPaymentIntent(saved.getTotal(), saved.getPublicId(), saved.contactEmail());
 92	                saved.setStripePaymentIntentId(intent.getId());
 93	                orderDAO.save(saved);
 94	                clientSecret = intent.getClientSecret();
 95	            } catch (StripeException ex) {
 96	                log.error("Stripe rejected the PaymentIntent for order {}", saved.getPublicId(), ex);
 97	                throw ApiException.badRequest("Could not start payment: " + ex.getMessage());
 98	            }
 99	        } else {
100	            log.warn("Stripe is not configured — order {} created without a PaymentIntent", saved.getPublicId());
101	        }
102	
103	        // Announce it and stop caring who acts on it. Listeners registered for AFTER_COMMIT
104	        // will not run until this @Transactional method actually commits, which is the point:
105	        // nobody gets emailed about an order that is about to be rolled back.
106	        events.publishEvent(OrderPlacedEvent.from(saved));
107	
108	        return new OrderCreateResponseDTO(toDtoWithItems(saved.getPublicId()), clientSecret);
109	    }
110	
111	    @Override
112	    @Transactional(readOnly = true)
113	    public OrderDTO getOrderByPublicId(UUID id) {
114	        return toDtoWithItems(id);
115	    }
116	
117	    /**
118	     * Asks Stripe directly rather than trusting our own record.
119	     *
120	     * <p>The confirmation page polls this because webhooks do not reach localhost unless
121	     * {@code stripe listen} is running — and even in production a webhook can be delayed.
122	     */
123	    @Override
124	    @Transactional
125	    public OrderDTO refreshPaymentStatus(UUID id) {
126	        CustomerOrder order = orderDAO.findByPublicId(id).orElseThrow(() -> ApiException.notFound("Order", id));
127	
128	        if (order.getStatus() == OrderStatus.PENDING_PAYMENT
129	                && order.getStripePaymentIntentId() != null
130	                && stripeService.isConfigured()) {
131	            try {
132	                PaymentIntent intent = stripeService.retrieve(order.getStripePaymentIntentId());
133	                if ("succeeded".equals(intent.getStatus())) {
134	                    order.setStatus(OrderStatus.PAID);
135	                    captureCardDetails(order, intent);
136	                    orderDAO.save(order);
137	                }
138	            } catch (StripeException ex) {
139	                log.warn("Could not refresh payment status for order {}", id, ex);
140	            }
141	        }
142	
143	        return toDtoWithItems(id);
144	    }
145	
146	    @Override
147	    @Transactional(readOnly = true)
148	    public Page<OrderDTO> getMyOrders(String userEmail, Pageable pageable) {
149	        User user =
150	                userDAO.findByEmail(userEmail).orElseThrow(() -> ApiException.notFound("No account for " + userEmail));
151	        return orderDAO.findByUser(user.getId(), pageable).map(mapper::mapCustomerOrderToOrderDTO);
152	    }
153	
154	    @Override
155	    @Transactional(readOnly = true)
156	    public Page<OrderDTO> getAllOrders(Pageable pageable) {
157	        return orderDAO.getAll(pageable).map(mapper::mapCustomerOrderToOrderDTO);
158	    }
159	
160	    @Override
161	    @Transactional
162	    public OrderDTO updateStatus(UUID id, OrderStatus status) {
163	        CustomerOrder order = orderDAO.findByPublicId(id).orElseThrow(() -> ApiException.notFound("Order", id));
164	        log.info("Order {} moving {} -> {}", id, order.getStatus(), status);
165	        order.setStatus(status);
166	        orderDAO.save(order);
167	        return toDtoWithItems(id);
168	    }
169	
170	    @Override
171	    @Transactional
172	    public void markPaid(String paymentIntentId) {
173	        orderDAO.findByPaymentIntentId(paymentIntentId)
174	                .ifPresentOrElse(
175	                        order -> {
176	                            // Webhooks can be delivered more than once, so this must be idempotent:
177	                            // only move an order forward from PENDING_PAYMENT.
178	                            if (order.getStatus() == OrderStatus.PENDING_PAYMENT) {
179	                                order.setStatus(OrderStatus.PAID);
180	                                try {
181	                                    captureCardDetails(order, stripeService.retrieve(paymentIntentId));
182	                                } catch (StripeException ex) {
183	                                    log.warn("Could not read card details for {}", paymentIntentId, ex);
184	                                }
185	                                orderDAO.save(order);
186	                                log.info("Order {} marked PAID via webhook", order.getPublicId());
187	                            } else {
188	                                log.info(
189	                                        "Ignoring duplicate webhook for order {} (already {})",
190	                                        order.getPublicId(),
191	                                        order.getStatus());
192	                            }
193	                        },
194	                        () -> log.warn("Webhook referenced unknown PaymentIntent {}", paymentIntentId));
195	    }
196	
197	    /**
198	     * Records WHICH card paid, for display on the confirmation page and order history.
199	     *
200	     * <p>Only the brand and last four digits are kept — the same display metadata Stripe reports.
201	     * The order deliberately does not keep the payment-method token: it needs to say which card was
202	     * used, never to be able to charge it again.
203	     *
204	     * <p>Best-effort. A failure here must never stop an order being marked paid — the customer's
205	     * money has already moved, and a missing "Visa ending 4242" is cosmetic.
206	     */
207	    private void captureCardDetails(CustomerOrder order, PaymentIntent intent) {
208	        try {
209	            String paymentMethodId = intent.getPaymentMethod();
210	            if (paymentMethodId == null) {
211	                return;
212	            }
213	
214	            PaymentMethod method = stripeService.retrievePaymentMethod(paymentMethodId);
215	            PaymentMethod.Card card = method.getCard();
216	
217	            if (card != null) {
218	                order.setCardBrand(card.getBrand());
219	                order.setCardLast4(card.getLast4());
220	                return;
221	            }
222	
223	            /*
224	             * Not every payment method is a card.
225	             *
226	             * Stripe Elements also offers wallets — Link, Cash App Pay, Klarna — and those have no
227	             * `card` object at all, not on the PaymentMethod and not on the Charge either. Assuming
228	             * a card is always there is why this silently recorded nothing at first.
229	             *
230	             * So fall back to the payment method's TYPE. "Paid with Link" is honest and useful;
231	             * inventing a last4 that Stripe never gave us would not be.
232	             */
233	            order.setCardBrand(method.getType());
234	            order.setCardLast4(null);
235	        } catch (StripeException ex) {
236	            log.warn("Could not read the payment method used for order {}", order.getPublicId(), ex);
237	        }
238	    }
239	
240	    private OrderDTO toDtoWithItems(UUID id) {
241	        return orderDAO.findByPublicIdWithItems(id)
242	                .map(mapper::mapCustomerOrderToOrderDTO)
243	                .orElseThrow(() -> ApiException.notFound("Order", id));
244	    }
245	}

