161	    @Transactional
162	    public OrderDTO updateStatus(UUID id, OrderStatus status) {
163	        CustomerOrder order = orderDAO.findByPublicId(id).orElseThrow(() -> ApiException.notFound("Order", id));
164	        log.info("Order {} moving {} -> {}", id, order.getStatus(), status);
165	        order.setStatus(status);
166	        orderDAO.save(order);
167	        return toDtoWithItems(id);
168	    }
169	
170	    @Override
171	    @Transactional
172	    public void markPaid(String paymentIntentId) {
173	        orderDAO.findByPaymentIntentId(paymentIntentId)
174	                .ifPresentOrElse(
175	                        order -> {
176	                            // Webhooks can be delivered more than once, so this must be idempotent:
177	                            // only move an order forward from PENDING_PAYMENT.
178	                            if (order.getStatus() == OrderStatus.PENDING_PAYMENT) {
179	                                order.setStatus(OrderStatus.PAID);
180	                                try {
181	                                    captureCardDetails(order, stripeService.retrieve(paymentIntentId));
182	                                } catch (StripeException ex) {
183	                                    log.warn("Could not read card details for {}", paymentIntentId, ex);
184	                                }
185	                                orderDAO.save(order);
186	                                log.info("Order {} marked PAID via webhook", order.getPublicId());
187	                            } else {
188	                                log.info(
189	                                        "Ignoring duplicate webhook for order {} (already {})",
190	                                        order.getPublicId(),
191	                                        order.getStatus());
192	                            }
193	                        },
194	                        () -> log.warn("Webhook referenced unknown PaymentIntent {}", paymentIntentId));
195	    }
196	
197	    /**
198	     * Records WHICH card paid, for display on the confirmation page and order history.
199	     *
200	     * <p>Only the brand and last four digits are kept — the same display metadata Stripe reports.
201	     * The order deliberately does not keep the payment-method token: it needs to say which card was
202	     * used, never to be able to charge it again.
203	     *
204	     * <p>Best-effort. A failure here must never stop an order being marked paid — the customer's
205	     * money has already moved, and a missing "Visa ending 4242" is cosmetic.
206	     */
207	    private void captureCardDetails(CustomerOrder order, PaymentIntent intent) {
208	        try {
209	            String paymentMethodId = intent.getPaymentMethod();
210	            if (paymentMethodId == null) {
211	                return;
212	            }
213	
214	            PaymentMethod method = stripeService.retrievePaymentMethod(paymentMethodId);
215	            PaymentMethod.Card card = method.getCard();
216	
217	            if (card != null) {
218	                order.setCardBrand(card.getBrand());
219	                order.setCardLast4(card.getLast4());
220	                return;
221	            }
222	
223	            /*
224	             * Not every payment method is a card.
225	             *
226	             * Stripe Elements also offers wallets — Link, Cash App Pay, Klarna — and those have no
227	             * `card` object at all, not on the PaymentMethod and not on the Charge either. Assuming
228	             * a card is always there is why this silently recorded nothing at first.
229	             *
230	             * So fall back to the payment method's TYPE. "Paid with Link" is honest and useful;
231	             * inventing a last4 that Stripe never gave us would not be.
232	             */
233	            order.setCardBrand(method.getType());
234	            order.setCardLast4(null);
235	        } catch (StripeException ex) {
236	            log.warn("Could not read the payment method used for order {}", order.getPublicId(), ex);
237	        }
238	    }
239	
240	    private OrderDTO toDtoWithItems(UUID id) {
241	        return orderDAO.findByPublicIdWithItems(id)
242	                .map(mapper::mapCustomerOrderToOrderDTO)
243	                .orElseThrow(() -> ApiException.notFound("Order", id));
244	    }
245	}

