  1	package com.pizza.api.entity.user;
  2	
  3	import com.pizza.api.dto.AddressCreateDTO;
  4	import com.pizza.api.dto.AddressDTO;
  5	import com.pizza.api.dto.PaymentMethodCreateDTO;
  6	import com.pizza.api.dto.PaymentMethodDTO;
  7	import com.pizza.api.dto.SetupIntentDTO;
  8	import com.pizza.api.exception.ApiException;
  9	import com.pizza.api.payment.StripeService;
 10	import com.stripe.exception.StripeException;
 11	import com.stripe.model.PaymentMethod;
 12	import java.util.List;
 13	import java.util.UUID;
 14	import lombok.extern.slf4j.Slf4j;
 15	import org.springframework.beans.factory.annotation.Autowired;
 16	import org.springframework.stereotype.Service;
 17	import org.springframework.transaction.annotation.Transactional;
 18	
 19	@Service
 20	@Slf4j
 21	public class UserProfileServiceImpl implements UserProfileService {
 22	
 23	    @Autowired
 24	    private UserDAO userDAO;
 25	
 26	    @Autowired
 27	    private UserAddressRepository addressRepository;
 28	
 29	    @Autowired
 30	    private UserPaymentMethodRepository paymentMethodRepository;
 31	
 32	    @Autowired
 33	    private StripeService stripeService;
 34	
 35	    // ================================================================ addresses
 36	
 37	    @Override
 38	    @Transactional(readOnly = true)
 39	    public List<AddressDTO> getAddresses(String email) {
 40	        User user = requireUser(email);
 41	        return addressRepository.findByUserIdOrderByPrimaryDescCreatedAtDesc(user.getId()).stream()
 42	                .map(this::toDto)
 43	                .toList();
 44	    }
 45	
 46	    @Override
 47	    @Transactional
 48	    public AddressDTO addAddress(String email, AddressCreateDTO dto) {
 49	        User user = requireUser(email);
 50	
 51	        UserAddress address = UserAddress.builder()
 52	                .user(user)
 53	                .label(dto.label())
 54	                .recipientName(dto.recipientName())
 55	                .phone(dto.phone())
 56	                .line1(dto.line1())
 57	                .line2(dto.line2())
 58	                .city(dto.city())
 59	                .state(dto.state())
 60	                .postalCode(dto.postalCode())
 61	                .build();
 62	
 63	        // The very first address is automatically primary — otherwise a customer could end up
 64	        // with saved addresses and nothing selected at checkout.
 65	        boolean first = addressRepository
 66	                .findByUserIdOrderByPrimaryDescCreatedAtDesc(user.getId())
 67	                .isEmpty();
 68	        address.setPrimary(first || Boolean.TRUE.equals(dto.primary()));
 69	
 70	        UserAddress saved = addressRepository.saveAndFlush(address);
 71	        if (saved.isPrimary()) {
 72	            demoteOtherAddresses(user.getId(), saved.getId());
 73	        }
 74	        return toDto(saved);
 75	    }
 76	
 77	    @Override
 78	    @Transactional
 79	    public AddressDTO updateAddress(String email, UUID addressId, AddressCreateDTO dto) {
 80	        User user = requireUser(email);
 81	        UserAddress address = requireOwnedAddress(user, addressId);
 82	
 83	        address.setLabel(dto.label());
 84	        address.setRecipientName(dto.recipientName());
 85	        address.setPhone(dto.phone());
 86	        address.setLine1(dto.line1());
 87	        address.setLine2(dto.line2());
 88	        address.setCity(dto.city());
 89	        address.setState(dto.state());
 90	        address.setPostalCode(dto.postalCode());
 91	
 92	        if (Boolean.TRUE.equals(dto.primary())) {
 93	            address.setPrimary(true);
 94	        }
 95	
 96	        UserAddress saved = addressRepository.saveAndFlush(address);
 97	        if (saved.isPrimary()) {
 98	            demoteOtherAddresses(user.getId(), saved.getId());
 99	        }
100	        return toDto(saved);
101	    }
102	
103	    @Override
104	    @Transactional
105	    public AddressDTO makeAddressPrimary(String email, UUID addressId) {
106	        User user = requireUser(email);
107	        UserAddress address = requireOwnedAddress(user, addressId);
108	
109	        address.setPrimary(true);
110	        UserAddress saved = addressRepository.saveAndFlush(address);
111	        demoteOtherAddresses(user.getId(), saved.getId());
112	        return toDto(saved);
113	    }
114	
115	    @Override
116	    @Transactional
117	    public void deleteAddress(String email, UUID addressId) {
118	        User user = requireUser(email);
119	        UserAddress address = requireOwnedAddress(user, addressId);
120	
121	        boolean wasPrimary = address.isPrimary();
122	        address.setDeleted(true);
123	        addressRepository.saveAndFlush(address);
124	
125	        // Never leave a customer with addresses but no primary — promote the newest survivor.
126	        if (wasPrimary) {
127	            addressRepository.findByUserIdOrderByPrimaryDescCreatedAtDesc(user.getId()).stream()
128	                    .findFirst()
129	                    .ifPresent(next -> {
130	                        next.setPrimary(true);
131	                        addressRepository.saveAndFlush(next);
132	                    });
133	        }
134	    }
135	
136	    // ========================================================= payment methods
137	
138	    @Override
139	    @Transactional(readOnly = true)
140	    public List<PaymentMethodDTO> getPaymentMethods(String email) {
141	        User user = requireUser(email);
142	        return paymentMethodRepository.findByUserIdOrderByPrimaryDescCreatedAtDesc(user.getId()).stream()
143	                .map(this::toDto)
144	                .toList();
145	    }
146	
147	    @Override
148	    @Transactional
149	    public SetupIntentDTO createSetupIntent(String email) {
150	        User user = requireUser(email);
151	        requireStripe();
152	
153	        try {
154	            String customerId =
155	                    stripeService.ensureCustomer(user.getStripeCustomerId(), user.getEmail(), user.getFullName());
156	            if (!customerId.equals(user.getStripeCustomerId())) {
157	                user.setStripeCustomerId(customerId);
158	                userDAO.save(user);
159	            }
160	            return new SetupIntentDTO(
161	                    stripeService.createSetupIntent(customerId).getClientSecret());
162	        } catch (StripeException ex) {
163	            log.error("Stripe refused a SetupIntent for {}", email, ex);
164	            throw ApiException.badRequest("Could not start card setup: " + ex.getMessage());
165	        }
166	    }
167	
168	    @Override
169	    @Transactional
170	    public PaymentMethodDTO addPaymentMethod(String email, PaymentMethodCreateDTO dto) {
171	        User user = requireUser(email);
172	        requireStripe();
173	
174	        try {
175	            String customerId =
176	                    stripeService.ensureCustomer(user.getStripeCustomerId(), user.getEmail(), user.getFullName());
177	            if (!customerId.equals(user.getStripeCustomerId())) {
178	                user.setStripeCustomerId(customerId);
179	                userDAO.save(user);
180	            }
181	
182	            // Attach so the card can be charged again later, then read back the DISPLAY metadata.
183	            // We never see or store the card itself — only what Stripe reports about it.
184	            PaymentMethod stripeMethod = stripeService.attachPaymentMethod(dto.stripePaymentMethodId(), customerId);
185	            PaymentMethod.Card card = stripeMethod.getCard();
186	
187	            UserPaymentMethod method = UserPaymentMethod.builder()
188	                    .user(user)
189	                    .stripePaymentMethodId(stripeMethod.getId())
190	                    .brand(card == null ? null : card.getBrand())
191	                    .last4(card == null ? null : card.getLast4())
192	                    .expMonth(card == null ? null : Math.toIntExact(card.getExpMonth()))
193	                    .expYear(card == null ? null : Math.toIntExact(card.getExpYear()))
194	                    .build();
195	
196	            boolean first = paymentMethodRepository
197	                    .findByUserIdOrderByPrimaryDescCreatedAtDesc(user.getId())
198	                    .isEmpty();
199	            method.setPrimary(first || Boolean.TRUE.equals(dto.primary()));
200	
201	            UserPaymentMethod saved = paymentMethodRepository.saveAndFlush(method);
202	            if (saved.isPrimary()) {
203	                demoteOtherPaymentMethods(user.getId(), saved.getId());
204	            }
205	            log.info("Saved a {} ending {} for {}", saved.getBrand(), saved.getLast4(), email);
206	            return toDto(saved);
207	        } catch (StripeException ex) {
208	            log.error("Stripe refused to attach a payment method for {}", email, ex);
209	            throw ApiException.badRequest("Could not save that card: " + ex.getMessage());
210	        }
211	    }
212	
213	    @Override
214	    @Transactional
215	    public PaymentMethodDTO makePaymentMethodPrimary(String email, UUID paymentMethodId) {
216	        User user = requireUser(email);
217	        UserPaymentMethod method = requireOwnedPaymentMethod(user, paymentMethodId);
218	
219	        method.setPrimary(true);
220	        UserPaymentMethod saved = paymentMethodRepository.saveAndFlush(method);
221	        demoteOtherPaymentMethods(user.getId(), saved.getId());
222	        return toDto(saved);
223	    }
224	
225	    @Override
226	    @Transactional
227	    public void deletePaymentMethod(String email, UUID paymentMethodId) {
228	        User user = requireUser(email);
229	        UserPaymentMethod method = requireOwnedPaymentMethod(user, paymentMethodId);
230	
231	        // Detach at Stripe too, so a "deleted" card genuinely cannot be charged again. Failing to
232	        // do that would leave a usable token behind — the row would be gone but the card would not.
233	        if (stripeService.isConfigured()) {
234	            try {
235	                stripeService.detachPaymentMethod(method.getStripePaymentMethodId());
236	            } catch (StripeException ex) {
237	                log.warn("Could not detach {} at Stripe", method.getStripePaymentMethodId(), ex);
238	            }
239	        }
240	
241	        boolean wasPrimary = method.isPrimary();
242	        method.setDeleted(true);
243	        paymentMethodRepository.saveAndFlush(method);
244	
245	        if (wasPrimary) {
246	            paymentMethodRepository.findByUserIdOrderByPrimaryDescCreatedAtDesc(user.getId()).stream()
247	                    .findFirst()
248	                    .ifPresent(next -> {
249	                        next.setPrimary(true);
250	                        paymentMethodRepository.saveAndFlush(next);
251	                    });
252	        }
253	    }
254	
255	    // ================================================================== helpers
256	
257	    private User requireUser(String email) {
258	        if (email == null) {
259	            throw ApiException.unauthorized("You must be signed in");
260	        }
261	        return userDAO.findByEmail(email).orElseThrow(() -> ApiException.notFound("No account for " + email));
262	    }
263	
264	    /**
265	     * Ownership check.
266	     *
267	     * <p>Deliberately a 404, not a 403: telling someone "that exists but is not yours" confirms the
268	     * id is real. To a caller who does not own it, it simply does not exist.
269	     */
270	    private UserAddress requireOwnedAddress(User user, UUID addressId) {
271	        return addressRepository
272	                .findByPublicId(addressId)
273	                .filter(a -> a.getUser().getId().equals(user.getId()))
274	                .orElseThrow(() -> ApiException.notFound("Address", addressId));
275	    }
276	
277	    private UserPaymentMethod requireOwnedPaymentMethod(User user, UUID paymentMethodId) {
278	        return paymentMethodRepository
279	                .findByPublicId(paymentMethodId)
280	                .filter(m -> m.getUser().getId().equals(user.getId()))
281	                .orElseThrow(() -> ApiException.notFound("Payment method", paymentMethodId));
282	    }
283	
284	    /** "Exactly one primary" cannot be a database constraint in MySQL, so it is enforced here. */
285	    private void demoteOtherAddresses(Long userId, Long keepId) {
286	        for (UserAddress other : addressRepository.findByUserIdOrderByPrimaryDescCreatedAtDesc(userId)) {
287	            if (!other.getId().equals(keepId) && other.isPrimary()) {
288	                other.setPrimary(false);
289	                addressRepository.save(other);
290	            }
291	        }
292	    }
293	
294	    private void demoteOtherPaymentMethods(Long userId, Long keepId) {
295	        for (UserPaymentMethod other : paymentMethodRepository.findByUserIdOrderByPrimaryDescCreatedAtDesc(userId)) {
296	            if (!other.getId().equals(keepId) && other.isPrimary()) {
297	                other.setPrimary(false);
298	                paymentMethodRepository.save(other);
299	            }
300	        }
301	    }
302	
303	    private void requireStripe() {
304	        if (!stripeService.isConfigured()) {
305	            throw ApiException.badRequest("Stripe is not configured on the server, so cards cannot be saved. "
306	                    + "Set pizza.stripe.secret-key and run with the local profile.");
307	        }
308	    }
309	
310	    private AddressDTO toDto(UserAddress a) {
311	        return new AddressDTO(
312	                a.getPublicId(),
313	                a.getLabel(),
314	                a.getRecipientName(),
315	                a.getPhone(),
316	                a.getLine1(),
317	                a.getLine2(),
318	                a.getCity(),
319	                a.getState(),
320	                a.getPostalCode(),
321	                a.isPrimary());
322	    }
323	
324	    private PaymentMethodDTO toDto(UserPaymentMethod m) {
325	        return new PaymentMethodDTO(
326	                m.getPublicId(), m.getBrand(), m.getLast4(), m.getExpMonth(), m.getExpYear(), m.isPrimary());
327	    }
328	}
