 24	/**
 25	 * A saved card — as a TOKEN, never as card data.
 26	 *
 27	 * <p><b>There is deliberately no card number, no CVC and no cardholder name on this entity.</b>
 28	 * Storing a PAN drags an application into PCI-DSS scope, and it is unnecessary: Stripe holds the
 29	 * card and gives us an opaque {@code pm_...} handle that is worthless without our secret key.
 30	 *
 31	 * <p>{@code brand}, {@code last4} and the expiry are DISPLAY metadata that Stripe itself returns,
 32	 * kept only so the customer can recognise "Visa ending 4242" in a list. If you find yourself
 33	 * adding a {@code cardNumber} field, stop.
 34	 */
 35	@Builder
 36	@Data
 37	@AllArgsConstructor
 38	@NoArgsConstructor
 39	@JsonInclude(value = Include.NON_NULL)
 40	@DynamicUpdate
 41	@Entity
 42	@SQLRestriction("deleted = false")
 43	@Table(
 44	        name = DatabaseTableNames.USER_PAYMENT_METHOD,
 45	        indexes = {@Index(name = "idx_user_payment_method_user", columnList = "user_id")})
 46	public class UserPaymentMethod implements Serializable {
 47	
 48	    @Serial
 49	    private static final long serialVersionUID = 1L;
 50	
 51	    @Id
 52	    @GeneratedValue(strategy = GenerationType.IDENTITY)
 53	    @Column(name = "id", nullable = false, updatable = false, unique = true)
 54	    private Long id;
 55	
 56	    @JdbcTypeCode(SqlTypes.CHAR)
 57	    @Column(name = "public_id", nullable = false, updatable = false, unique = true, length = 36)
 58	    private UUID publicId;
 59	
 60	    @ToString.Exclude
 61	    @EqualsAndHashCode.Exclude
 62	    @ManyToOne(fetch = FetchType.LAZY, optional = false)
 63	    @JoinColumn(name = "user_id", nullable = false)
 64	    private User user;
 65	
 66	    /** The opaque Stripe handle. This is the only thing that can actually charge the card. */
 67	    @Column(name = "stripe_payment_method_id", nullable = false, length = 120)
 68	    private String stripePaymentMethodId;
 69	
 70	    @Column(name = "brand", length = 40)
 71	    private String brand;
 72	
 73	    /** Display only — the last four digits Stripe reports. NOT the card number. */
 74	    @Column(name = "last4", length = 4)
 75	    private String last4;
 76	
 77	    @Column(name = "exp_month")
 78	    private Integer expMonth;
 79	
 80	    @Column(name = "exp_year")
 81	    private Integer expYear;
 82	
 83	    @Builder.Default
 84	    @Column(name = "is_primary", nullable = false)
 85	    private boolean primary = false;
 86	
 87	    @Builder.Default
 88	    @Column(name = "deleted", nullable = false)
 89	    private boolean deleted = false;
 90	
 91	    @CreationTimestamp
 92	    @Column(name = "created_at", nullable = false, updatable = false)
 93	    private LocalDateTime createdAt;
 94	
 95	    @UpdateTimestamp
 96	    @Column(name = "updated_at", nullable = false)
 97	    private LocalDateTime updatedAt;
 98	
 99	    @PrePersist
100	    private void preCreate() {
101	        if (publicId == null) {
102	            publicId = UUID.randomUUID();
103	        }
104	    }
105	}
