  3	-- Saved addresses and saved payment methods, both belonging to a user account.
  4	--
  5	-- ============================================================================
  6	-- ⚠️  READ THIS BEFORE ADDING COLUMNS TO user_payment_method
  7	-- ============================================================================
  8	-- There is NO card number here, no CVC, and no cardholder name. Storing a PAN puts an application
  9	-- squarely inside PCI-DSS scope, and there is no reason to: Stripe already holds the card and
 10	-- hands back an opaque token.
 11	--
 12	-- What is stored is:
 13	--   * stripe_payment_method_id — an opaque "pm_..." token. Useless to anyone without our secret key.
 14	--   * brand / last4 / exp_month / exp_year — DISPLAY metadata only, returned by Stripe itself,
 15	--     so the customer can recognise "Visa ending 4242" in a list.
 16	--
 17	-- The card details themselves never touch this application, let alone this database.
 18	-- ============================================================================
 19	
 20	--changeset pizza:700-add-stripe-customer-id
 21	--comment Links our user to a Stripe Customer, which is what payment methods attach to
 22	ALTER TABLE app_user ADD COLUMN stripe_customer_id VARCHAR(120) NULL;
 23	CREATE INDEX idx_app_user_stripe_customer ON app_user (stripe_customer_id);
 24	--rollback ALTER TABLE app_user DROP COLUMN stripe_customer_id;
 25	
 26	--changeset pizza:701-create-user-address
 27	--comment Guests do not get rows here — a guest types their address onto the order itself
 28	CREATE TABLE user_address (
 29	    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
 30	    public_id      CHAR(36)     NOT NULL,
 31	    user_id        BIGINT       NOT NULL,
 32	    label          VARCHAR(60)  NULL COMMENT 'Home, Work, ... purely for the customer',
 33	    recipient_name VARCHAR(150) NULL,
 34	    phone          VARCHAR(40)  NULL,
 35	    line1          VARCHAR(200) NOT NULL,
 36	    line2          VARCHAR(200) NULL,
 37	    city           VARCHAR(100) NOT NULL,
 38	    state          VARCHAR(50)  NOT NULL,
 39	    postal_code    VARCHAR(20)  NOT NULL,
 40	    is_primary     BOOLEAN      NOT NULL DEFAULT FALSE,
 41	    deleted        BOOLEAN      NOT NULL DEFAULT FALSE,
 42	    created_at     DATETIME(6)  NOT NULL,
 43	    updated_at     DATETIME(6)  NOT NULL,
 44	    CONSTRAINT uk_user_address_public_id UNIQUE (public_id),
 45	    CONSTRAINT fk_user_address_user FOREIGN KEY (user_id) REFERENCES app_user (id) ON DELETE CASCADE
 46	);
 47	CREATE INDEX idx_user_address_user ON user_address (user_id);
 48	--rollback DROP TABLE user_address;
 49	
 50	--changeset pizza:702-create-user-payment-method
 51	--comment Tokens and display metadata only. See the warning at the top of this file.
 52	CREATE TABLE user_payment_method (
 53	    id                       BIGINT AUTO_INCREMENT PRIMARY KEY,
 54	    public_id                CHAR(36)     NOT NULL,
 55	    user_id                  BIGINT       NOT NULL,
 56	    stripe_payment_method_id VARCHAR(120) NOT NULL COMMENT 'Opaque pm_... token from Stripe',
 57	    brand                    VARCHAR(40)  NULL COMMENT 'visa, mastercard, ... for display',
 58	    last4                    CHAR(4)      NULL COMMENT 'Display only. NOT the card number.',
 59	    exp_month                INT          NULL,
 60	    exp_year                 INT          NULL,
 61	    is_primary               BOOLEAN      NOT NULL DEFAULT FALSE,
 62	    deleted                  BOOLEAN      NOT NULL DEFAULT FALSE,
